import assert from 'node:assert/strict';
import test from 'node:test';
import { readSession, seedSession, updateSession } from '../src/session-store.js';

function deferred() {
  let resolve;
  const promise = new Promise((done) => { resolve = done; });
  return { promise, resolve };
}

test('preserves independent concurrent session patches', async () => {
  seedSession('s1', { theme: 'light', locale: 'en' });
  const first = deferred();
  const second = deferred();
  const theme = updateSession('s1', { theme: 'dark' }, first.promise);
  const locale = updateSession('s1', { locale: 'ro' }, second.promise);
  first.resolve();
  second.resolve();
  await Promise.all([theme, locale]);
  assert.deepEqual(readSession('s1'), { theme: 'dark', locale: 'ro' });
});

